INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(300, 'barrier', '/ˈbæriər/', 'noun', '{"zh-TW":["障礙；壁壘","障礙；屏障"],"en":["a fence or obstacle that prevents movement or access","something that prevents movement or access"]}', '{"root":{"text":"bar","meaning":"bar/block (阻擋)"},"suffix":{"text":"-ier","meaning":"thing that (…的東西)"},"logic":"阻擋的東西，即「障礙」。"}', 'trade barrier / language barrier / barrier to entry; language barrier / trade barrier / break down barriers', '[{"en":"Language barriers can hinder international business.","zh-TW":"語言障礙可能妨礙國際商務。"},{"en":"The company faced significant barriers to entry.","zh-TW":"公司面臨重大的進入門檻。"},{"en":"Language can be a barrier to communication.","zh-TW":"語言可能是溝通的障礙。"},{"en":"They are trying to break down trade barriers.","zh-TW":"他們正試圖消除貿易障礙。"}]', NULL, NULL, 3, 300, 513),
(301, 'base', '/beɪs/', 'noun', '{"zh-TW":["基礎；基地","以…為基礎"],"en":["the lowest part or foundation","to use as a starting point"]}', '{"root":{"text":"bas","meaning":"bottom (底部)"},"logic":"底部基礎，即「基礎」。"}', 'customer base / base on / base salary', '[{"en":"The company has a large customer base in Asia.","zh-TW":"公司在亞洲擁有龐大的客戶群。"},{"en":"The decision was based on thorough research.","zh-TW":"該決定基於深入研究。"}]', '{"adjective":"basic","adverb":"basically"}', NULL, 1, 301, NULL),
(302, 'baseline', '/ˈbeɪslaɪn/', 'noun', '{"zh-TW":["基準線；基線"],"en":["a starting point used for comparison or measurement of progress"]}', NULL, 'set a baseline / baseline measurement / performance baseline', '[{"en":"The baseline for the project was established at the kickoff meeting.","zh-TW":"項目的基準線在啟動會議上確立。"},{"en":"Performance is measured against the established baseline.","zh-TW":"績效根據既定基準線進行衡量。"}]', '{"adjective":"baseline"}', NULL, 3, 302, 827),
(303, 'basic', '/ˈbeɪsɪk/', 'adjective', '{"zh-TW":["基本的；基礎的"],"en":["forming the most important part"]}', NULL, 'basic knowledge / basic needs', '[{"en":"You need basic computer skills.","zh-TW":"你需要基本的電腦技能。"},{"en":"Food and water are basic needs.","zh-TW":"食物和水是基本需求。"}]', '{"noun":"basics","adverb":"basically"}', NULL, 2, 303, NULL),
(304, 'basis', '/ˈbeɪsɪs/', 'noun', '{"zh-TW":["基礎；依據","基礎；根據"],"en":["the underlying support or foundation for something","the underlying support or foundation"]}', '{"root":{"text":"bas","meaning":"bottom (底部)"},"suffix":{"text":"-is","meaning":"noun ending (名詞字尾)"},"logic":"底部的根基，即「基礎」。"}', 'on a regular basis / on the basis of; on the basis of / daily basis / regular basis', '[{"en":"Reports are submitted on a weekly basis.","zh-TW":"報告每週提交一次。"},{"en":"Candidates are selected on the basis of experience.","zh-TW":"候選人根據經驗進行篩選。"},{"en":"Employees are evaluated on a regular basis.","zh-TW":"員工定期接受評估。"},{"en":"On what basis did you make that decision?","zh-TW":"你根據什麼做出那個決定？"}]', '{"adjective":"basic","adverb":"basically"}', NULL, 2, 304, 514),
(305, 'batch', '/bætʃ/', 'noun', '{"zh-TW":["批次；一批"],"en":["a quantity of goods produced in one operation"]}', NULL, 'batch processing / production batch', '[{"en":"The factory produced a batch of 500 units today.","zh-TW":"工廠今天生產了500個單位的一批產品。"},{"en":"Batch processing reduces production costs for large orders.","zh-TW":"批次處理降低了大訂單的生產成本。"}]', '{"verb":"batch","adjective":"batched"}', NULL, 2, 305, NULL),
(306, 'bath', '/bæθ/', 'noun', '{"zh-TW":["洗澡；浴缸","沐浴；浴缸"],"en":["an act of washing the body","washing the body; a container for water"]}', NULL, 'take a bath / bath towel; take a bath / bathroom', '[{"en":"I take a bath every evening.","zh-TW":"我每天晚上洗澡。"},{"en":"The bath is full of hot water.","zh-TW":"浴缸裡滿是熱水。"},{"en":"The bathroom is on the second floor.","zh-TW":"浴室在二樓。"}]', '{"verb":"bathe","noun2":"bathroom"}', NULL, 1, 306, NULL),
(307, 'battle', '/ˈbætəl/', 'noun', '{"zh-TW":["戰鬥；鬥爭"],"en":["a fight between armed forces"]}', NULL, 'battle against / battle field', '[{"en":"The battle lasted three days.","zh-TW":"戰鬥持續了三天。"},{"en":"She won her battle against cancer.","zh-TW":"她贏得了與癌症的鬥爭。"}]', '{"verb":"battle"}', NULL, 2, 307, NULL),
(308, 'beach', '/biːtʃ/', 'noun', '{"zh-TW":["海灘"],"en":["an area of sand beside the sea"]}', NULL, 'on the beach / beach volleyball', '[{"en":"We spent the day at the beach.","zh-TW":"我們在海灘度過了一天。"},{"en":"The beach was crowded in summer.","zh-TW":"夏天海灘很擁擠。"}]', NULL, NULL, 2, 308, NULL),
(309, 'bear', '/beər/', 'verb', '{"zh-TW":["【主要意義-名詞】熊","【次要意義-動詞】承受；忍耐","【次要意義-動詞】產出；帶來（結果）","【次要意義-動詞】朝向某方向移動"],"en":["[primary - noun] a large wild animal","[secondary - verb] to carry a weight or responsibility; to endure","[secondary - verb] to produce something such as fruit or results","[secondary - verb] to move or turn in a particular direction"]}', '{"root":{"text":"bear","meaning":"carry (攜帶)"},"logic":"攜帶重量，即「承擔」。"}', 'bear in mind / bear fruit / bear responsibility / bear left / bear witness', '[{"en":"Please bear in mind that the deadline cannot be extended.","zh-TW":"請記住截止日期無法延後。"},{"en":"The new strategy is beginning to bear fruit after six months.","zh-TW":"新策略在六個月後開始顯現成效。"},{"en":"The company must bear full responsibility for the product defect.","zh-TW":"公司必須對產品缺陷承擔全部責任。"}]', '{"noun":"bearing","adjective":"bearable"}', 'bear 作動詞有多個高頻用法：bear in mind（記住），bear fruit（結出成果），bear responsibility（承擔責任），這些均為 TOEIC 商業文章必考表達，與名詞「熊」完全無關。', 1, 309, NULL),
(310, 'bear out', '/beər aʊt/', 'phrasal verb', '{"zh-TW":["【主要意義】證實；支持；佐證"],"en":["[primary] to confirm or support the truth of something","[secondary] to justify or vindicate a claim or statement"]}', NULL, 'bear out a claim / bear out a theory / bear someone out', '[{"en":"The financial data bears out the auditor''s concerns about overspending.","zh-TW":"財務數據證實了審計人員對超支的擔憂。"},{"en":"His performance in the interview bore out our initial impression of him.","zh-TW":"他在面試中的表現證實了我們對他的最初印象。"},{"en":"The results bear out the hypothesis proposed last year.","zh-TW":"這些結果支持了去年提出的假設。"}]', '{"verb":"bear, bears, bore, borne"}', 'bear out 意為「證實/佐證」，常出現在 TOEIC 閱讀的報告分析或研究結論語境中，與 bear（熊）毫無關聯。', 3, 310, NULL),
(311, 'beat', '/biːt/', 'verb', '{"zh-TW":["打敗；跳動"],"en":["to defeat someone; to make a rhythm"]}', NULL, 'beat the record / heartbeat', '[{"en":"Our team beat theirs 3-1.","zh-TW":"我們隊以3比1打敗了他們。"},{"en":"My heart was beating fast.","zh-TW":"我的心跳得很快。"}]', '{"noun":"beat"}', NULL, 1, 311, NULL),
(312, 'beautiful', '/ˈbjuːtɪfəl/', 'adjective', '{"zh-TW":["美麗的","美麗的；漂亮的","美麗的；美好的"],"en":["very pleasing to look at or experience","very attractive or pleasing","very attractive; giving great pleasure"]}', NULL, 'beautiful weather / beautiful design; beautiful scenery / beautiful day; beautiful scenery/weather/music', '[{"en":"The office has a beautiful view.","zh-TW":"辦公室有很美的景觀。"},{"en":"Thank you for this beautiful gift.","zh-TW":"謝謝你這份美麗的禮物。"},{"en":"What a beautiful sunset!","zh-TW":"多美的日落啊！"},{"en":"She has a beautiful voice.","zh-TW":"她有一副美麗的嗓音。"},{"en":"What a beautiful day!","zh-TW":"多麼美好的一天！"},{"en":"She wore a beautiful dress.","zh-TW":"她穿了一件漂亮的洋裝。"}]', '{"adjective":"beautiful","noun":"beauty","adverb":"beautifully","verb":"beautify"}', NULL, 3, 312, NULL),
(313, 'because', '/bɪˈkɒz/', 'conjunction', '{"zh-TW":["因為"],"en":["for the reason that"]}', NULL, 'because of / just because', '[{"en":"I stayed home because I was sick.","zh-TW":"我因為生病待在家裡。"},{"en":"The game was canceled because of rain.","zh-TW":"比賽因為下雨被取消了。"}]', NULL, NULL, 3, 313, NULL),
(314, 'become', '/bɪˈkʌm/', 'verb', '{"zh-TW":["變成；成為","成為；變得"],"en":["to begin to be; to grow to be","to begin to be something","to begin to be; to start being"]}', NULL, 'become aware / become available; become aware / become friends; become + adj/noun', '[{"en":"He became the new manager.","zh-TW":"他成為了新經理。"},{"en":"The product has become very popular.","zh-TW":"這個產品變得非常受歡迎。"},{"en":"She became a doctor.","zh-TW":"她成為了一名醫生。"},{"en":"It''s becoming colder.","zh-TW":"天氣越來越冷了。"},{"en":"The situation became worse.","zh-TW":"情況變得更糟了。"}]', '{"verb":"become"}', NULL, 2, 314, NULL),
(315, 'bed', '/bɛd/', 'noun', '{"zh-TW":["床","床；花壇"],"en":["a piece of furniture for sleeping","a piece of furniture for sleeping on"]}', NULL, 'go to bed / in bed; go to bed / make the bed / bed and breakfast', '[{"en":"Time to go to bed.","zh-TW":"該上床睡覺了。"},{"en":"He stayed in bed all day.","zh-TW":"他整天待在床上。"},{"en":"I usually go to bed at 11 PM.","zh-TW":"我通常晚上11點上床睡覺。"},{"en":"Please make your bed.","zh-TW":"請整理你的床。"}]', '{"noun2":"bedroom","noun3":"bedding","noun":"bedding, bedroom"}', NULL, 1, 315, NULL),
(316, 'before', '/bɪˈfɔːr/', 'preposition, conjunction, adverb', '{"zh-TW":["在...之前"],"en":["earlier than; at an earlier time"]}', NULL, 'before + V-ing / the day before', '[{"en":"Finish your work before the deadline.","zh-TW":"在截止日期前完成你的工作。"},{"en":"I''ve never been here before.","zh-TW":"我以前從未來過這裡。"}]', NULL, NULL, 2, 316, NULL),
(317, 'begin', '/bɪˈɡɪn/', 'verb', '{"zh-TW":["開始","開始；著手"],"en":["to start","to start doing something","to start; to do the first part of something"]}', NULL, 'begin with / to begin with; begin to do / begin doing / begin with', '[{"en":"The workshop begins at 10 a.m.","zh-TW":"研習會在上午10點開始。"},{"en":"Let us begin with the agenda.","zh-TW":"讓我們從議程開始。"},{"en":"The meeting begins at 9.","zh-TW":"會議9點開始。"},{"en":"Let''s begin with introductions.","zh-TW":"讓我們從自我介紹開始。"},{"en":"The meeting begins at 9 AM.","zh-TW":"會議上午九點開始。"},{"en":"Let''s begin with the first item on the agenda.","zh-TW":"讓我們從議程的第一項開始。"}]', '{"verb":"begin","noun":"beginning","noun2":"beginner"}', NULL, 2, 317, NULL),
(318, 'behalf', '/bɪˈhɑːf/', 'noun', '{"zh-TW":["代表；為了…的利益","代表"],"en":["in the interest of; as a representative of"]}', '{"prefix":{"text":"be-","meaning":"by (在旁)"},"root":{"text":"half","meaning":"side (邊)"},"logic":"在某人的邊（一方），即「代表」。"}', 'on behalf of / on sb''s behalf; on behalf of / act on someone''s behalf', '[{"en":"I''m writing on behalf of the marketing department.","zh-TW":"我代表行銷部門寫信。"},{"en":"The lawyer acted on behalf of the client.","zh-TW":"律師代表客戶行事。"},{"en":"I am writing on behalf of my client.","zh-TW":"我代表我的客戶寫信。"},{"en":"She accepted the award on behalf of the team.","zh-TW":"她代表團隊接受了獎項。"}]', NULL, NULL, 2, 318, NULL),
(319, 'behave', '/bɪˈheɪv/', 'verb', '{"zh-TW":["行為；表現"],"en":["to act in a particular way","to conduct oneself properly"]}', '{"prefix":{"text":"be-","meaning":"thoroughly (徹底)"},"root":{"text":"have","meaning":"hold oneself (持有自己)"},"logic":"徹底持有自己的方式，即「行為」。"}', 'behave professionally / consumer behavior', '[{"en":"Employees are expected to behave professionally.","zh-TW":"員工應表現專業。"},{"en":"Market conditions cause consumers to behave differently.","zh-TW":"市場條件使消費者行為有所不同。"}]', '{"noun":"behavior"}', NULL, 2, 319, NULL),
(320, 'behind', '/bɪˈhaɪnd/', 'preposition', '{"zh-TW":["在…後面；落後","在…後面","在...後面；落後"],"en":["at the back of","less advanced than","at the back of; not making enough progress"]}', NULL, 'fall behind / behind schedule; behind schedule / fall behind; behind schedule / fall behind / leave behind', '[{"en":"The project is behind schedule.","zh-TW":"專案進度落後了。"},{"en":"Who is behind this decision?","zh-TW":"誰在這個決定背後？"},{"en":"The cat hid behind the sofa.","zh-TW":"貓躲在沙發後面。"},{"en":"We''re behind schedule.","zh-TW":"我們落後於進度了。"},{"en":"The garden is behind the house.","zh-TW":"花園在房子後面。"},{"en":"We''re behind schedule on this project.","zh-TW":"我們這個專案進度落後。"}]', '{"preposition":"behind","adverb":"behind"}', NULL, 2, 320, NULL),
(321, 'believe', '/bɪˈliːv/', 'verb', '{"zh-TW":["相信；認為"],"en":["to think something is true","to have confidence in","to accept as true","to think something is true; to have faith"]}', NULL, 'believe in / hard to believe; believe in / believe it or not', '[{"en":"I believe this strategy will work.","zh-TW":"我相信這個策略會成功。"},{"en":"We believe in teamwork.","zh-TW":"我們相信團隊合作。"},{"en":"I believe you''re right.","zh-TW":"我相信你是對的。"},{"en":"Do you believe in ghosts?","zh-TW":"你相信有鬼嗎？"},{"en":"I believe this plan will work.","zh-TW":"我相信這個計畫會成功。"},{"en":"She doesn''t believe in ghosts.","zh-TW":"她不相信鬼。"}]', '{"verb":"believe","noun":"belief","adjective":"believable","adjective2":"unbelievable"}', NULL, 3, 321, NULL),
(322, 'belong', '/bɪˈlɒŋ/', 'verb', '{"zh-TW":["屬於","屬於；適合在"],"en":["to be the property of","to be the property of; to be in the right place"]}', NULL, 'belong to / a sense of belonging', '[{"en":"This book belongs to me.","zh-TW":"這本書是我的。"},{"en":"She felt she didn''t belong.","zh-TW":"她覺得自己不屬於這裡。"},{"en":"These files belong in the cabinet.","zh-TW":"這些文件應該放在櫃子裡。"}]', '{"noun":"belonging"}', NULL, 2, 322, NULL),
(323, 'below', '/bɪˈloʊ/', 'preposition', '{"zh-TW":["在…下面","在...下面；低於"],"en":["at a lower level than","at a lower level than; less than"]}', NULL, 'below average / see below; below average / below zero', '[{"en":"The temperature dropped below zero.","zh-TW":"溫度降到了零度以下。"},{"en":"See the chart below.","zh-TW":"請看下面的圖表。"},{"en":"The temperature dropped below zero.","zh-TW":"氣溫降到零度以下。"},{"en":"See the chart below.","zh-TW":"請見下方圖表。"}]', NULL, NULL, 2, 323, NULL),
(324, 'benchmark', '/ˈbentʃmɑːrk/', 'noun', '{"zh-TW":["基準；標竿"],"en":["a standard or point of reference for comparison","a standard for comparison"]}', '{"root":{"text":"bench","meaning":"bench (長凳)"},"suffix":{"text":"mark","meaning":"mark (標記)"},"logic":"長凳上的標記（測量基準），即「基準」。"}', 'industry benchmark / set a benchmark / benchmark against', '[{"en":"Our service quality sets the benchmark in the industry.","zh-TW":"我們的服務品質樹立了行業基準。"},{"en":"We benchmark our performance against competitors.","zh-TW":"我們以競爭對手為基準評估績效。"},{"en":"This sets a new benchmark for quality.","zh-TW":"這為品質設立了新的標竿。"},{"en":"We measure performance against industry benchmarks.","zh-TW":"我們以產業基準來衡量績效。"}]', '{"verb":"benchmark","noun":"benchmark","noun2":"benchmarking"}', NULL, 3, 324, 278),
(325, 'benchmarking', '/ˈbentʃˌmɑːrkɪŋ/', 'noun', '{"zh-TW":["基準分析；標竿學習"],"en":["comparing performance metrics to industry best practices"]}', NULL, 'competitive benchmarking / internal benchmarking', '[{"en":"Benchmarking revealed we lagged behind competitors in speed.","zh-TW":"基準分析顯示我們在速度上落後於競爭對手。"},{"en":"We use benchmarking to identify areas for improvement.","zh-TW":"我們使用基準分析來識別改進領域。"}]', '{"verb":"benchmark","noun":"benchmark"}', NULL, 4, 325, 753),
(326, 'bend', '/bɛnd/', 'verb', '{"zh-TW":["彎曲；屈身"],"en":["to make something curved"]}', NULL, 'bend down / bend the rules', '[{"en":"Bend your knees slightly.","zh-TW":"稍微彎曲膝蓋。"},{"en":"She bent down to pick it up.","zh-TW":"她彎腰撿起來。"}]', NULL, NULL, 1, 326, NULL),
(327, 'beneath', '/bɪˈniːθ/', 'preposition', '{"zh-TW":["在…下方"],"en":["in or to a lower position than; under"]}', '{"prefix":{"text":"be-","meaning":"by (在)"},"root":{"text":"neath","meaning":"below (下方)"},"logic":"在下方的位置。"}', 'beneath the surface / beneath one''s dignity', '[{"en":"The treasure was buried beneath the old tree.","zh-TW":"寶藏埋在老樹下方。"},{"en":"Beneath the surface, there are many problems.","zh-TW":"表面之下有許多問題。"}]', NULL, NULL, 3, 327, NULL),
(328, 'beneficiary', '/ˌbenɪˈfɪʃiəri/', 'noun', '{"zh-TW":["受益人"],"en":["a person or entity entitled to receive benefits from a policy or trust"]}', NULL, 'name a beneficiary / policy beneficiary / trust beneficiary', '[{"en":"She named her children as beneficiaries of her life insurance policy.","zh-TW":"她將子女列為人壽保險保單的受益人。"},{"en":"The beneficiary received the full payout upon the policyholder''s death.","zh-TW":"受益人在保單持有人死亡後獲得了全額賠付。"}]', '{"plural":"beneficiaries"}', NULL, 4, 328, NULL),
(329, 'benefit', '/ˈbenɪfɪt/', 'noun', '{"zh-TW":["利益；好處","福利"],"en":["an advantage or profit gained","a payment made by the state or employer"]}', '{"root":{"text":"bene","meaning":"good (好)"},"suffix":{"text":"-fit","meaning":"do/make (做)"},"logic":"做好事帶來的，即「利益」。"}', 'benefit from / employee benefits / mutual benefit', '[{"en":"Both parties will benefit from this partnership.","zh-TW":"雙方都將從這個合作中受益。"},{"en":"The company offers excellent employee benefits.","zh-TW":"公司提供優秀的員工福利。"}]', '{"adjective":"beneficial"}', NULL, 3, 329, 12),
(330, 'benefits', '/ˈbɛnɪfɪts/', 'noun', '{"zh-TW":["福利；員工福利"],"en":["non-wage compensation provided to employees"]}', NULL, 'employee benefits / benefits package', '[{"en":"The benefits package includes health insurance and a pension.","zh-TW":"福利待遇包括健康保險和退休金。"},{"en":"Many employees value good benefits over higher salaries.","zh-TW":"許多員工重視良好福利勝過更高薪資。"}]', '{"verb":"benefit","adjective":"beneficial"}', NULL, 3, 330, NULL),
(331, 'beside', '/bɪˈsaɪd/', 'preposition', '{"zh-TW":["在…旁邊"],"en":["next to; at the side of"]}', NULL, 'beside the point / sit beside', '[{"en":"Come and sit beside me.","zh-TW":"來坐在我旁邊。"},{"en":"That''s beside the point.","zh-TW":"那不是重點。"}]', NULL, NULL, 2, 331, NULL),
(332, 'besides', '/bɪˈsaɪdz/', 'preposition', '{"zh-TW":["除了…之外"],"en":["in addition to; apart from"]}', '{"prefix":{"text":"be-","meaning":"by (在旁)"},"root":{"text":"sides","meaning":"sides (邊)"},"logic":"在旁邊之外還有，即「除了…之外」。"}', 'besides that / besides me', '[{"en":"Besides English, she speaks French and German.","zh-TW":"除了英語，她還會說法語和德語。"},{"en":"Besides the cost, there are other concerns.","zh-TW":"除了費用之外，還有其他顧慮。"}]', NULL, NULL, 3, 332, NULL),
(333, 'best', '/best/', 'adjective, adverb, noun', '{"zh-TW":["最好的；最佳地"],"en":["of the highest quality; most well"]}', NULL, 'do one''s best / at best / best practice', '[{"en":"She is the best student in class.","zh-TW":"她是班上最好的學生。"},{"en":"We did our best to finish on time.","zh-TW":"我們盡了最大努力準時完成。"}]', NULL, NULL, 1, 333, NULL),
(334, 'beta', '/ˈbeɪtə/', 'noun', '{"zh-TW":["測試版"],"en":["an early version of a product for testing"]}', NULL, 'beta version / beta testing', '[{"en":"The app is still in beta.","zh-TW":"這個應用程式還在測試階段。"},{"en":"Beta testers found several bugs.","zh-TW":"測試用戶發現了幾個錯誤。"}]', NULL, NULL, 1, 334, NULL),
(335, 'better', '/ˈbetər/', 'adjective, adverb', '{"zh-TW":["更好的；更好地"],"en":["of a higher standard; more well"]}', NULL, 'had better (最好...) / get better', '[{"en":"This solution is better than the last one.","zh-TW":"這個方案比上一個好。"},{"en":"You''d better leave now.","zh-TW":"你最好現在離開。"}]', '{"verb":"better"}', NULL, 2, 335, NULL),
(336, 'between', '/bɪˈtwiːn/', 'preposition', '{"zh-TW":["在…之間","在...之間（兩者）"],"en":["in the space or time separating two things","in the space separating two things"]}', NULL, 'between meetings / in between; between you and me / in between; between A and B / in between', '[{"en":"The interview is between 2 and 3 p.m.","zh-TW":"面試在下午2點到3點之間。"},{"en":"Choose between the two options.","zh-TW":"在兩個選項之間做選擇。"},{"en":"The shop is between the bank and the post office.","zh-TW":"商店在銀行和郵局之間。"},{"en":"Between you and me, I don''t like him.","zh-TW":"你我之間說，我不喜歡他。"},{"en":"The meeting is between 2 and 4 PM.","zh-TW":"會議在下午2點到4點之間。"}]', '{"preposition":"between"}', NULL, 3, 336, NULL),
(337, 'beverage', '/ˈbɛvərɪdʒ/', 'noun', '{"zh-TW":["飲料；飲品"],"en":["a drink of any type"]}', NULL, 'hot beverage / cold beverage', '[{"en":"The beverage menu includes both alcoholic and non-alcoholic options.","zh-TW":"飲料菜單包含酒精和非酒精選項。"},{"en":"Complimentary beverages are served during the flight.","zh-TW":"飛行期間提供免費飲料。"}]', NULL, NULL, 3, 337, NULL),
(338, 'beyond', '/bɪˈjɒnd/', 'preposition', '{"zh-TW":["超越；在…之外"],"en":["further away than; outside the limits of"]}', '{"prefix":{"text":"be-","meaning":"by (在)"},"root":{"text":"yond","meaning":"that side (那邊)"},"logic":"在那邊之外，即「超越」。"}', 'beyond expectations / beyond doubt / go beyond', '[{"en":"The results went beyond our expectations.","zh-TW":"結果超出了我們的預期。"},{"en":"This task is beyond my abilities.","zh-TW":"這項任務超出了我的能力。"}]', NULL, NULL, 2, 338, NULL),
(339, 'biannual', '/baɪˈænjuəl/', 'adjective', '{"zh-TW":["每兩年一次的；每年兩次的"],"en":["occurring twice a year or every two years"]}', NULL, 'biannual review / biannual report', '[{"en":"A biannual performance review is conducted in June and December.","zh-TW":"每年兩次的績效審查在六月和十二月進行。"},{"en":"The board meets for a biannual strategic assessment.","zh-TW":"董事會每兩年進行一次戰略評估。"}]', '{"adverb":"biannually"}', NULL, 3, 339, NULL),
(340, 'bid', '/bɪd/', 'noun', '{"zh-TW":["出價；投標"],"en":["an offer of a price for something","an attempt to achieve something"]}', '{"root":{"text":"bid","meaning":"offer (提供)"},"logic":"提供價格，即「出價」。"}', 'submit a bid / highest bidder', '[{"en":"Three companies submitted bids for the project.","zh-TW":"三家公司對該專案提交了投標。"},{"en":"The winning bid was $4.5 million.","zh-TW":"中標金額為450萬美元。"}]', '{"noun":"bidder"}', NULL, 1, 340, NULL),
(341, 'big', '/bɪɡ/', 'adjective', '{"zh-TW":["大的","大的；重要的"],"en":["of considerable size or extent","large in size; important"]}', NULL, 'big deal / big picture; a big deal / big business', '[{"en":"They live in a big house.","zh-TW":"他們住在一棟大房子裡。"},{"en":"It''s no big deal.","zh-TW":"這沒什麼大不了的。"},{"en":"This is a big decision.","zh-TW":"這是一個重大決定。"}]', NULL, NULL, 1, 341, NULL),
(342, 'bilateral', '/baɪˈlætərəl/', 'adjective', '{"zh-TW":["雙邊的"],"en":["involving two parties, especially countries"]}', '{"prefix":{"text":"bi-","meaning":"two (二)"},"root":{"text":"later","meaning":"side (邊)"},"suffix":{"text":"-al","meaning":"relating to (有關的)"},"logic":"與兩邊有關的，即「雙邊的」。"}', 'bilateral agreement/trade/relations', '[{"en":"The two countries signed a bilateral trade agreement.","zh-TW":"兩國簽署了雙邊貿易協定。"},{"en":"Bilateral relations have improved significantly.","zh-TW":"雙邊關係已顯著改善。"}]', NULL, NULL, 3, 342, 959),
(343, 'bill', '/bɪl/', 'noun', '{"zh-TW":["帳單；費用"],"en":["a list of charges to be paid"]}', NULL, 'pay the bill / split the bill', '[{"en":"We asked the waiter for the bill after dessert.","zh-TW":"吃完甜點後我們要求服務生結帳。"},{"en":"Let''s split the bill equally among the four of us.","zh-TW":"讓我們四個人平分帳單。"}]', '{"verb":"bill","adjective":"billed"}', NULL, 1, 343, NULL),
(344, 'billion', 'ˈbɪljən', 'noun', '{"zh-TW":["十億","龐大數量"],"en":["a thousand million","an extremely large number"]}', NULL, 'one billion/billion-dollar', '[{"en":"The company is now worth one billion dollars.","zh-TW":"公司現在價值十億美元。"}]', '{"adjective":"billion-dollar"}', NULL, 3, 344, NULL),
(345, 'bind', '/baɪnd/', 'verb', '{"zh-TW":["綁定；約束"],"en":["to tie or fasten tightly","to impose a legal obligation"]}', '{"root":{"text":"bind","meaning":"tie (綁)"},"logic":"源自古英語 bindan（綁住）。"}', 'legally binding / bind together', '[{"en":"The contract is legally binding.","zh-TW":"這份合約具有法律約束力。"},{"en":"The agreement binds both parties.","zh-TW":"協議對雙方都有約束力。"}]', '{"noun":"binding","adjective":"binding"}', NULL, 1, 345, NULL),
(346, 'binding', 'ˈbaɪndɪŋ', 'adjective', '{"zh-TW":["具有約束力的；有效的","必須遵守的"],"en":["legally enforceable","obligatory"]}', NULL, 'legally binding/binding agreement', '[{"en":"This is a legally binding contract.","zh-TW":"這是一份具有法律約束力的合約。"}]', '{"verb":"bind","noun":"binding"}', NULL, 3, 346, 515),
(347, 'biodegradable', '/ˌbaɪəʊdɪˈɡreɪdəbəl/', 'adjective', '{"zh-TW":["可生物降解的"],"en":["capable of being decomposed naturally by living organisms"]}', NULL, 'biodegradable packaging / biodegradable material', '[{"en":"The company replaced plastic with biodegradable packaging.","zh-TW":"公司將塑膠替換為可生物降解包裝。"},{"en":"Biodegradable products reduce environmental pollution.","zh-TW":"可生物降解產品減少了環境污染。"}]', '{"noun":"biodegradation","verb":"biodegrade"}', NULL, 5, 347, NULL),
(348, 'biodiversity', '/ˌbaɪəʊdaɪˈvɜːrsɪti/', 'noun', '{"zh-TW":["生物多樣性"],"en":["the variety of plant and animal life in an ecosystem"]}', NULL, 'protect biodiversity / loss of biodiversity', '[{"en":"Deforestation threatens biodiversity in tropical regions.","zh-TW":"森林砍伐威脅熱帶地區的生物多樣性。"},{"en":"Conservation efforts aim to preserve biodiversity.","zh-TW":"保育工作旨在保護生物多樣性。"}]', '{"adjective":"biodiverse"}', NULL, 4, 348, NULL),
(349, 'bird', '/bɜːrd/', 'noun', '{"zh-TW":["鳥"],"en":["a creature with wings and feathers","an animal with wings and feathers that can usually fly"]}', NULL, 'early bird / bird''s eye view; early bird / bird''s-eye view', '[{"en":"A bird was singing in the tree.","zh-TW":"一隻鳥在樹上唱歌。"},{"en":"The early bird catches the worm.","zh-TW":"早起的鳥兒有蟲吃。"},{"en":"We saw many birds in the park.","zh-TW":"我們在公園看到很多鳥。"}]', NULL, NULL, 1, 349, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(350, 'birth', '/bɜːrθ/', 'noun', '{"zh-TW":["出生；誕生"],"en":["the process of being born"]}', NULL, 'give birth / date of birth', '[{"en":"She gave birth to twins.","zh-TW":"她生了雙胞胎。"},{"en":"What is your date of birth?","zh-TW":"你的出生日期是什麼？"}]', '{"noun2":"birthday"}', NULL, 2, 350, NULL),
(351, 'bistro', '/ˈbiːstrəʊ/', 'noun', '{"zh-TW":["小酒館；餐廳"],"en":["a small, informal restaurant"]}', NULL, 'French bistro / neighborhood bistro', '[{"en":"We found a charming bistro near the city center.","zh-TW":"我們在市中心附近找到了一家迷人的小酒館。"},{"en":"The bistro specializes in traditional French dishes.","zh-TW":"這家小酒館專門供應傳統法國菜餚。"}]', NULL, NULL, 2, 351, NULL),
(352, 'bite', '/baɪt/', 'verb', '{"zh-TW":["咬"],"en":["to use teeth to cut into something"]}', NULL, 'bite off / insect bite', '[{"en":"The dog bit his hand.","zh-TW":"狗咬了他的手。"},{"en":"Don''t bite off more than you can chew.","zh-TW":"不要貪多嚼不爛。"}]', NULL, NULL, 1, 352, NULL),
(353, 'bitter', '/ˈbɪtər/', 'adjective', '{"zh-TW":["苦的；痛苦的"],"en":["having a sharp unpleasant taste"]}', NULL, 'bitter cold / bitter experience', '[{"en":"This coffee tastes bitter.","zh-TW":"這咖啡嘗起來很苦。"},{"en":"It was a bitter experience.","zh-TW":"那是一段痛苦的經歷。"}]', '{"noun":"bitterness","adverb":"bitterly"}', NULL, 2, 353, NULL),
(354, 'black', '/blæk/', 'adjective', '{"zh-TW":["黑色的","黑色的；黑暗的"],"en":["the darkest color","having the darkest color; very dark"]}', NULL, 'black and white / black market; black and white / in the black (有盈餘)', '[{"en":"She was wearing a black dress.","zh-TW":"她穿著一件黑色洋裝。"},{"en":"It''s not a black and white issue.","zh-TW":"這不是一個非黑即白的問題。"},{"en":"The company is finally in the black.","zh-TW":"公司終於有盈餘了。"}]', NULL, NULL, 2, 354, NULL),
(355, 'blame', '/bleɪm/', 'verb', '{"zh-TW":["責備；歸咎"],"en":["to say someone is responsible for something bad"]}', NULL, 'blame for / take the blame', '[{"en":"Don''t blame me for your mistake.","zh-TW":"別把你的錯怪到我頭上。"},{"en":"He took the blame for everything.","zh-TW":"他承擔了所有的責任。"}]', NULL, NULL, 2, 355, NULL),
(356, 'blank', '/blæŋk/', 'adjective', '{"zh-TW":["空白的"],"en":["with nothing written or printed on it"]}', NULL, 'blank page / draw a blank', '[{"en":"Fill in the blank spaces.","zh-TW":"填寫空白處。"},{"en":"My mind went blank.","zh-TW":"我的腦袋一片空白。"}]', NULL, NULL, 2, 356, NULL),
(357, 'blind', '/blaɪnd/', 'adjective', '{"zh-TW":["瞎的；盲目的"],"en":["unable to see"]}', NULL, 'turn a blind eye / blind spot', '[{"en":"He has been blind since birth.","zh-TW":"他生下來就看不見。"},{"en":"Don''t turn a blind eye to injustice.","zh-TW":"不要對不公正視而不見。"}]', '{"noun":"blindness","adverb":"blindly"}', NULL, 2, 357, NULL),
(358, 'blizzard', '/ˈblɪzərd/', 'noun', '{"zh-TW":["暴風雪"],"en":["a severe snowstorm with strong winds"]}', '{"root":{"text":"blizzard","meaning":"violent blow (猛烈吹襲)"},"logic":"指伴隨強風的猛烈暴風雪。"}', 'caught in a blizzard / blizzard conditions', '[{"en":"The blizzard shut down all major highways.","zh-TW":"暴風雪導致所有主要公路關閉。"},{"en":"Schools were closed due to the blizzard.","zh-TW":"學校因暴風雪停課。"}]', NULL, NULL, 3, 358, NULL),
(359, 'block', '/blɒk/', 'noun', '{"zh-TW":["街區；障礙物"],"en":["a solid piece; an area of buildings"]}', NULL, 'road block / around the block', '[{"en":"The office is two blocks away.","zh-TW":"辦公室在兩個街區外。"},{"en":"A tree blocked the road.","zh-TW":"一棵樹擋住了路。"}]', '{"verb":"block"}', NULL, 2, 359, NULL),
(360, 'blockchain', '/ˈblɒktʃeɪn/', 'noun', '{"zh-TW":["區塊鏈"],"en":["a distributed digital ledger recording transactions securely across many computers"]}', NULL, 'blockchain technology / blockchain network / apply blockchain', '[{"en":"Blockchain technology ensures tamper-proof transaction records.","zh-TW":"區塊鏈技術確保了防篡改的交易記錄。"},{"en":"Supply chain transparency improved through blockchain implementation.","zh-TW":"通過實施區塊鏈改善了供應鏈透明度。"}]', '{"adjective":"blockchain-based"}', NULL, 4, 360, NULL),
(361, 'blood', '/blʌd/', 'noun', '{"zh-TW":["血液","血；血液","血液；血統"],"en":["the red liquid flowing through the body","the red liquid in your body","the red liquid that flows through the body"]}', NULL, 'blood pressure / blood test; blood pressure / blood test / in cold blood', '[{"en":"High blood pressure is a common issue.","zh-TW":"高血壓是常見的問題。"},{"en":"The doctor ordered a blood test.","zh-TW":"醫生安排了驗血。"},{"en":"She donated blood today.","zh-TW":"她今天捐了血。"},{"en":"High blood pressure is dangerous.","zh-TW":"高血壓是危險的。"},{"en":"He donated blood at the hospital.","zh-TW":"他在醫院捐血。"},{"en":"High blood pressure is a common condition.","zh-TW":"高血壓是常見的疾病。"}]', '{"noun":"blood","adjective":"bloody","verb":"bleed"}', NULL, 2, 361, NULL),
(362, 'blow', '/bloʊ/', 'verb', '{"zh-TW":["吹；打擊"],"en":["to send air from the mouth","to move air; a hard hit or shock"]}', NULL, 'blow up / blow out; blow up / blow out / a blow to', '[{"en":"The wind blew the leaves away.","zh-TW":"風把樹葉吹走了。"},{"en":"Blow out the candles.","zh-TW":"吹滅蠟燭。"},{"en":"The wind is blowing hard today.","zh-TW":"今天風吹得很大。"},{"en":"Losing the contract was a blow to the company.","zh-TW":"失去合約對公司是一個打擊。"}]', NULL, NULL, 1, 362, NULL),
(363, 'blue', '/bluː/', 'adjective', '{"zh-TW":["藍色的；憂鬱的"],"en":["the color of the sky on a clear day","having the color of the sky; sad"]}', NULL, 'out of the blue / feeling blue; out of the blue (突然) / feel blue', '[{"en":"The sky is bright blue today.","zh-TW":"今天天空是亮藍色的。"},{"en":"The news came out of the blue.","zh-TW":"這消息來得很突然。"},{"en":"The sky is clear and blue.","zh-TW":"天空清澈湛藍。"}]', NULL, NULL, 1, 363, NULL),
(364, 'blueprint', '/ˈbluːprɪnt/', 'noun', '{"zh-TW":["藍圖；計畫","藍圖；詳細計畫"],"en":["a detailed plan or scheme","a detailed plan or design"]}', '{"root":{"text":"blue","meaning":"blue (藍色)"},"suffix":{"text":"print","meaning":"print (印刷)"},"logic":"藍色印刷的設計圖，即「藍圖」。"}', 'blueprint for success / strategic blueprint; blueprint for success / provide a blueprint', '[{"en":"The CEO presented a blueprint for the company''s future.","zh-TW":"執行長提出了公司未來的藍圖。"},{"en":"This plan serves as a blueprint for similar projects.","zh-TW":"此計畫可作為類似專案的藍圖。"},{"en":"This is our blueprint for expansion.","zh-TW":"這是我們的擴張藍圖。"},{"en":"The report provides a blueprint for reform.","zh-TW":"報告提供了改革的藍圖。"}]', '{"noun":"blueprint"}', NULL, 3, 364, 828),
(365, 'bluetooth', '/ˈbluːtuːθ/', 'noun', '{"zh-TW":["藍牙"],"en":["wireless technology for short-range data exchange"]}', NULL, 'bluetooth connection / bluetooth speaker', '[{"en":"Connect your headphones via Bluetooth.","zh-TW":"透過藍牙連接你的耳機。"},{"en":"Is your Bluetooth turned on?","zh-TW":"你的藍牙開了嗎？"}]', NULL, NULL, 3, 365, NULL),
(366, 'board', '/bɔːrd/', 'noun', '{"zh-TW":["董事會；委員會","板"],"en":["a group of people who manage an organization","to get on a vehicle"]}', '{"root":{"text":"board","meaning":"plank/table (桌板)"},"logic":"圍著桌子開會的人，即「董事會」。"}', 'board of directors / board meeting / on board', '[{"en":"The board of directors approved the acquisition.","zh-TW":"董事會批准了收購案。"},{"en":"All passengers must board 30 minutes before departure.","zh-TW":"所有乘客必須在起飛前30分鐘登機。"}]', NULL, NULL, 2, 366, 279),
(367, 'boardroom', '/ˈbɔːrdruːm/', 'noun', '{"zh-TW":["董事會會議室；會議室"],"en":["a room where a board of directors meets"]}', NULL, 'boardroom meeting / boardroom presentation', '[{"en":"The quarterly review was held in the boardroom.","zh-TW":"季度審查在董事會會議室舉行。"},{"en":"A major decision was announced from the boardroom.","zh-TW":"一項重大決定從董事會會議室宣布。"}]', NULL, NULL, 3, 367, NULL),
(368, 'boat', '/boʊt/', 'noun', '{"zh-TW":["船；小艇"],"en":["a vehicle for traveling on water","a small vessel for traveling on water"]}', NULL, 'by boat / in the same boat; by boat / in the same boat (同命運)', '[{"en":"We crossed the lake by boat.","zh-TW":"我們乘船穿過了湖。"},{"en":"We''re all in the same boat.","zh-TW":"我們都處於同樣的處境。"},{"en":"They crossed the river by boat.","zh-TW":"他們搭船渡河。"},{"en":"We''re all in the same boat.","zh-TW":"我們都處於相同的處境。"}]', NULL, NULL, 1, 368, NULL),
(369, 'body', '/ˈbɒdi/', 'noun', '{"zh-TW":["身體；主體；機構","身體；主體","身體；團體；主體"],"en":["physical structure of a person","an organized group","the physical structure of a person","the physical structure of a person; a group"]}', NULL, 'body language / governing body; body language / body of work', '[{"en":"Body language is important in interviews.","zh-TW":"面試時肢體語言很重要。"},{"en":"The governing body approved the plan.","zh-TW":"管理機構批准了計畫。"},{"en":"Exercise is good for the body.","zh-TW":"運動對身體有好處。"},{"en":"His body language shows confidence.","zh-TW":"他的肢體語言展現了自信。"},{"en":"Exercise is good for the body.","zh-TW":"運動對身體有益。"},{"en":"The governing body approved the plan.","zh-TW":"管理機構批准了這個計畫。"}]', '{"noun":"body","adjective":"bodily"}', NULL, 1, 369, NULL),
(370, 'bold', '/boʊld/', 'adjective', '{"zh-TW":["大膽的；粗體的"],"en":["willing to take risks","(of text) in a thick dark type"]}', '{"root":{"text":"bold","meaning":"brave (勇敢)"},"logic":"源自古英語 bald（勇敢的）。"}', 'bold move / bold decision / bold font', '[{"en":"That was a bold decision to make.","zh-TW":"那是一個大膽的決定。"},{"en":"Please highlight the key words in bold.","zh-TW":"請用粗體標示關鍵字。"}]', '{"noun":"boldness","adverb":"boldly"}', NULL, 1, 370, NULL),
(371, 'bomb', '/bɒm/', 'noun', '{"zh-TW":["炸彈"],"en":["an explosive weapon"]}', NULL, 'drop a bomb / bomb threat', '[{"en":"The bomb was defused safely.","zh-TW":"炸彈被安全拆除了。"},{"en":"The news dropped like a bomb.","zh-TW":"這消息像炸彈一樣爆開。"}]', '{"verb":"bomb","noun2":"bomber","noun3":"bombing"}', NULL, 1, 371, NULL),
(372, 'bond', '/bɒnd/', 'noun', '{"zh-TW":["債券；紐帶"],"en":["a certificate of debt issued by a government or company","a connection or relationship"]}', '{"root":{"text":"bond","meaning":"bind (綁)"},"logic":"綁定的承諾，即「債券、紐帶」。"}', 'government bond / corporate bond / bond market', '[{"en":"Investors shifted their portfolio toward bonds.","zh-TW":"投資者將投資組合轉向債券。"},{"en":"The company issued bonds to raise capital.","zh-TW":"公司發行債券籌集資金。"}]', NULL, NULL, 1, 372, NULL),
(373, 'bone', '/boʊn/', 'noun', '{"zh-TW":["骨頭"],"en":["the hard parts inside the body","the hard parts inside the body that form the skeleton"]}', NULL, 'broken bone / bone dry; bone structure / to the bone', '[{"en":"She broke a bone in her foot.","zh-TW":"她腳上的一根骨頭斷了。"},{"en":"The dog buried the bone.","zh-TW":"狗把骨頭埋了起來。"},{"en":"She broke a bone in her leg.","zh-TW":"她腿骨骨折了。"},{"en":"The cold wind cut to the bone.","zh-TW":"寒風刺骨。"}]', '{"adjective":"bony"}', NULL, 1, 373, NULL),
(374, 'bonus', '/ˈboʊnəs/', 'noun', '{"zh-TW":["獎金；紅利"],"en":["additional payment given to an employee for good performance"]}', NULL, 'performance bonus / annual bonus / sign-on bonus / bonus scheme', '[{"en":"All employees received a year-end bonus this December.","zh-TW":"所有員工今年十二月都收到了年終獎金。"},{"en":"The sales team earned a bonus for exceeding targets.","zh-TW":"銷售團隊因超越目標而獲得獎金。"}]', '{"plural":"bonuses"}', NULL, 2, 374, 829),
(375, 'book', '/bʊk/', 'verb', '{"zh-TW":["【主要意義-名詞】書；書籍","【次要意義-動詞】預訂（座位/房間）；登記","【次要意義-動詞（法律/警察用語）】逮捕登記；記錄違規"],"en":["[primary - noun] a set of printed pages bound together","[secondary - verb] to reserve a seat, room, or service in advance","[secondary - verb] to officially record an arrest or charge against someone"]}', NULL, 'book a table / book a flight / fully booked / book someone for speeding', '[{"en":"All seats for the conference have been booked in advance.","zh-TW":"會議的所有座位都已提前預訂。"},{"en":"The hotel is fully booked during the trade show period.","zh-TW":"貿易展期間飯店已全部訂滿。"},{"en":"The officer booked him for driving without a valid license.","zh-TW":"警察以無有效駕照駕車的罪名將他逮捕登記。"}]', '{"noun":"booking, bookkeeper, bookkeeping"}', '動詞 book = 「預訂」是 TOEIC 最常考用法，book a room/flight/table 是必考句型；police book someone（逮捕登記）則較少見，但出現在新聞類文章中。', 1, 375, NULL),
(376, 'booking', '/ˈbʊkɪŋ/', 'noun', '{"zh-TW":["預訂"],"en":["a reservation for accommodation or travel"]}', NULL, 'online booking / advance booking', '[{"en":"Make your booking at least two weeks in advance.","zh-TW":"請至少提前兩週預訂。"},{"en":"The booking was confirmed by email.","zh-TW":"預訂已通過電子郵件確認。"}]', '{"verb":"book","adjective":"booked"}', NULL, 3, 376, NULL),
(377, 'bookkeeping', '/ˈbʊkˌkiːpɪŋ/', 'noun', '{"zh-TW":["簿記；記帳"],"en":["recording financial transactions in a systematic and orderly manner"]}', NULL, 'double-entry bookkeeping / bookkeeping software / outsource bookkeeping', '[{"en":"Accurate bookkeeping is essential for tax compliance.","zh-TW":"準確的簿記對稅務合規至關重要。"},{"en":"She handles all bookkeeping for the small business.","zh-TW":"她處理小企業的所有簿記工作。"}]', '{"noun":"bookkeeper","verb":"keep books"}', NULL, 4, 377, NULL),
(378, 'boost', '/buːst/', 'verb', '{"zh-TW":["提升；促進"],"en":["to increase or improve something"]}', '{"root":{"text":"boost","meaning":"push up (推高)"},"logic":"推高，即「提升」。"}', 'boost sales/productivity/morale', '[{"en":"The promotion helped boost sales by 25%.","zh-TW":"促銷活動幫助銷售增長了25%。"},{"en":"Team-building events can boost employee morale.","zh-TW":"團建活動能提升員工士氣。"}]', NULL, NULL, 2, 378, NULL),
(379, 'border', '/ˈbɔːrdər/', 'noun', '{"zh-TW":["邊界；國界"],"en":["the line that separates two countries"]}', NULL, 'cross the border / border control', '[{"en":"They crossed the border at night.","zh-TW":"他們夜間越過了邊境。"},{"en":"The town is on the border of France.","zh-TW":"這個鎮在法國的邊境上。"}]', NULL, NULL, 2, 379, NULL),
(380, 'born', '/bɔːrn/', 'adjective', '{"zh-TW":["出生的；天生的"],"en":["brought into life","brought into existence; having a natural ability"]}', NULL, 'born in / born leader; be born / born and raised', '[{"en":"She was born in 1990.","zh-TW":"她1990年出生。"},{"en":"He''s a born leader.","zh-TW":"他是一個天生的領導者。"},{"en":"She was born in 1990.","zh-TW":"她生於1990年。"},{"en":"He''s a born leader.","zh-TW":"他是天生的領導者。"}]', '{"noun":"birth"}', NULL, 1, 380, NULL),
(381, 'borrow', '/ˈbɒrəʊ/', 'verb', '{"zh-TW":["借入"],"en":["to take and use something belonging to someone else with the intention of returning it"]}', '{"root":{"text":"borrow","meaning":"pledge/surety (抵押)"},"logic":"以抵押方式取得，即「借入」。"}', 'borrow money/funds / borrow from', '[{"en":"The company borrowed $5 million to fund expansion.","zh-TW":"公司借入500萬美元資助擴張。"},{"en":"Interest rates affect how much businesses borrow.","zh-TW":"利率影響企業的借款金額。"}]', '{"noun":"borrower"}', NULL, 2, 381, NULL),
(382, 'boss', '/bɒs/', 'noun', '{"zh-TW":["老闆；上司","老闆；指揮"],"en":["a person who is in charge","a person in charge of others","the person in charge; to give orders"]}', NULL, 'the boss / report to the boss; like a boss / boss around; boss sb around', '[{"en":"My boss approved the budget.","zh-TW":"我的老闆批准了預算。"},{"en":"She is a great boss to work for.","zh-TW":"她是一個很好的上司。"},{"en":"My boss gave me a raise.","zh-TW":"我老闆給我加薪了。"},{"en":"Stop bossing me around.","zh-TW":"別再對我指手畫腳了。"},{"en":"My boss approved my vacation request.","zh-TW":"我的老闆批准了我的休假申請。"},{"en":"Stop bossing me around.","zh-TW":"別再對我發號施令。"}]', '{"noun":"boss","adjective":"bossy"}', NULL, 1, 382, NULL),
(383, 'both', '/boʊθ/', 'determiner', '{"zh-TW":["兩者都"],"en":["the two; each of two things","used to refer to two things or people together"]}', NULL, 'both... and / both sides; both...and... / both of', '[{"en":"Both answers are correct.","zh-TW":"兩個答案都正確。"},{"en":"She speaks both English and French.","zh-TW":"她英語和法語都會說。"},{"en":"Both options are acceptable.","zh-TW":"兩個選項都可以接受。"},{"en":"Both of them passed the exam.","zh-TW":"他們兩個都通過了考試。"}]', NULL, NULL, 1, 383, NULL),
(384, 'bother', '/ˈbɒðər/', 'verb', '{"zh-TW":["打擾；煩惱"],"en":["to annoy or trouble someone","to cause worry or annoyance","to make the effort to do something"]}', '{"root":{"text":"bother","meaning":"confuse/annoy (困擾)"},"logic":"指使人感到困擾或不安。"}', 'don''t bother / sorry to bother; don''t bother / sorry to bother you / it bothers me', '[{"en":"Sorry to bother you.","zh-TW":"抱歉打擾你了。"},{"en":"Don''t bother waiting for me.","zh-TW":"不用費心等我了。"},{"en":"Sorry to bother you, but I need help.","zh-TW":"抱歉打擾你，但我需要幫忙。"},{"en":"The noise doesn''t bother me.","zh-TW":"噪音不會困擾我。"}]', '{"noun":"bother","adjective":"bothersome"}', NULL, 2, 384, NULL),
(385, 'bottleneck', '/ˈbɒtəlnɛk/', 'noun', '{"zh-TW":["瓶頸"],"en":["a point of congestion that slows progress"]}', NULL, 'production bottleneck / identify bottlenecks', '[{"en":"Shipping is the main bottleneck.","zh-TW":"運輸是主要瓶頸。"},{"en":"We identified several bottlenecks in the process.","zh-TW":"我們找出了流程中的幾個瓶頸。"}]', '{"noun":"bottleneck"}', NULL, 4, 385, NULL),
(386, 'bottom', '/ˈbɒtəm/', 'noun', '{"zh-TW":["底部；最低處","底部；最低的"],"en":["the lowest part of something","the lowest part; at the lowest position"]}', NULL, 'at the bottom / from top to bottom; at the bottom of / bottom line', '[{"en":"Sign at the bottom of the page.","zh-TW":"在頁面底部簽名。"},{"en":"He started from the bottom.","zh-TW":"他從底層開始做起。"},{"en":"The bottom line is we need more funding.","zh-TW":"重點是我們需要更多資金。"}]', NULL, NULL, 2, 386, NULL),
(387, 'boundary', '/ˈbaʊndri/', 'noun', '{"zh-TW":["邊界；界線","邊界；界限"],"en":["a line that marks the limit of an area","a line marking the limits of an area"]}', '{"root":{"text":"bound","meaning":"limit (限制)"},"suffix":{"text":"-ary","meaning":"relating to (有關的)"},"logic":"與限制有關的，即「邊界」。"}', 'cross boundaries / set boundaries; set boundaries / cross a boundary / boundary line', '[{"en":"The project crosses departmental boundaries.","zh-TW":"該專案跨越了部門界線。"},{"en":"It''s important to set professional boundaries.","zh-TW":"設定專業界線很重要。"},{"en":"The river forms the boundary between the two countries.","zh-TW":"這條河構成兩國之間的邊界。"},{"en":"It''s important to set personal boundaries.","zh-TW":"設立個人界限很重要。"}]', '{"adjective":"bounded","verb":"bound"}', NULL, 3, 387, NULL),
(388, 'boutique', '/buːˈtiːk/', 'noun', '{"zh-TW":["精品店；小型專賣店"],"en":["a small shop selling fashionable items"]}', '{"root":{"text":"boutique","meaning":"small shop (小店)"},"logic":"源自法語，指販售精品的小型商店。"}', 'boutique hotel / fashion boutique', '[{"en":"She opened a boutique selling handmade jewelry.","zh-TW":"她開了一家賣手工飾品的精品店。"},{"en":"The boutique hotel offers personalized service.","zh-TW":"這家精品旅館提供個人化服務。"}]', NULL, NULL, 3, 388, NULL),
(389, 'bowl', '/boʊl/', 'noun', '{"zh-TW":["碗"],"en":["a round deep dish"]}', NULL, 'bowl of soup / mixing bowl', '[{"en":"Have a bowl of soup.","zh-TW":"喝一碗湯吧。"},{"en":"Put the salad in a large bowl.","zh-TW":"把沙拉放在一個大碗裡。"}]', NULL, NULL, 1, 389, NULL),
(390, 'box', '/bɒks/', 'noun', '{"zh-TW":["箱子；盒子"],"en":["a container with flat sides"]}', NULL, 'cardboard box / think outside the box', '[{"en":"She opened the box carefully.","zh-TW":"她小心地打開了盒子。"},{"en":"We need to think outside the box.","zh-TW":"我們需要跳出框架思考。"}]', NULL, NULL, 1, 390, NULL),
(391, 'brain', '/breɪn/', 'noun', '{"zh-TW":["大腦；腦力","大腦；頭腦"],"en":["the organ of thought","intelligence","the organ inside the head that controls the body"]}', NULL, 'brainstorm / brain drain; brain storm / brain power', '[{"en":"Let''s brainstorm some ideas.","zh-TW":"讓我們腦力激盪一些點子。"},{"en":"Brain drain is a serious issue.","zh-TW":"人才外流是嚴重的問題。"},{"en":"The brain controls all body functions.","zh-TW":"大腦控制所有的身體功能。"},{"en":"Use your brain!","zh-TW":"動動腦筋！"}]', '{"noun":"brain","adjective":"brainy","verb":"brainstorm"}', NULL, 2, 391, NULL),
(392, 'brainstorm', '/ˈbreɪnstɔːrm/', 'verb', '{"zh-TW":["腦力激盪；集思廣益"],"en":["to suggest many ideas quickly in a group"]}', NULL, 'brainstorm ideas / brainstorming session', '[{"en":"The team brainstormed solutions to the supply chain problem.","zh-TW":"團隊就供應鏈問題進行了腦力激盪。"},{"en":"The brainstorming session generated over 30 new ideas.","zh-TW":"腦力激盪會議產生了超過30個新想法。"}]', '{"noun":"brainstorm","noun2":"brainstorming"}', NULL, 4, 392, NULL),
(393, 'branch', '/brɑːntʃ/', 'noun', '{"zh-TW":["分公司；分支"],"en":["a division of a larger organization","a local office of a company"]}', '{"root":{"text":"branch","meaning":"arm/limb (樹枝/手臂)"},"logic":"從主體延伸出去的，即「分支」。"}', 'branch office / branch manager / open a branch', '[{"en":"The bank has over 200 branches nationwide.","zh-TW":"該銀行在全國有超過200家分行。"},{"en":"We plan to open a new branch in Taipei.","zh-TW":"我們計劃在台北開設新分公司。"}]', NULL, NULL, 2, 393, 77),
(394, 'brand', '/brænd/', 'noun', '{"zh-TW":["品牌","品牌；商標"],"en":["a type of product made by a particular company"]}', '{"root":{"text":"brand","meaning":"burn/mark (燒/標記)"},"logic":"燒印標記以識別，即「品牌」。"}', 'brand awareness / brand image / brand loyalty; brand name / brand loyalty / brand awareness', '[{"en":"Building a strong brand takes years of effort.","zh-TW":"建立強大的品牌需要多年努力。"},{"en":"The new campaign increased brand awareness by 30%.","zh-TW":"新活動將品牌知名度提高了30%。"},{"en":"This brand is known for its high quality.","zh-TW":"這個品牌以高品質聞名。"},{"en":"They are trying to build brand awareness.","zh-TW":"他們正努力建立品牌知名度。"}]', '{"noun":"branding","verb":"brand","adjective":"branded"}', NULL, 2, 394, NULL),
(395, 'branding', '/ˈbrændɪŋ/', 'noun', '{"zh-TW":["品牌塑造；品牌化"],"en":["the process of creating a distinctive identity for a company or product"]}', NULL, 'corporate branding / product branding / employer branding / personal branding', '[{"en":"Strong branding distinguishes the company from competitors.","zh-TW":"強大的品牌塑造使公司與競爭對手區別開來。"},{"en":"The rebranding effort modernized the company''s image.","zh-TW":"重新品牌化工作使公司形象現代化。"}]', '{"verb":"brand","noun":"brand"}', NULL, 3, 395, NULL),
(396, 'brave', '/breɪv/', 'adjective', '{"zh-TW":["勇敢的"],"en":["ready to face danger"]}', NULL, 'brave enough / brave face', '[{"en":"She was brave to speak up.","zh-TW":"她勇敢地站出來發言。"},{"en":"The brave soldier saved his team.","zh-TW":"勇敢的士兵拯救了他的隊伍。"}]', '{"noun":"bravery","adverb":"bravely"}', NULL, 2, 396, NULL),
(397, 'breach', '/briːtʃ/', 'noun', '{"zh-TW":["違反；破壞"],"en":["a failure to observe a law, agreement, or code of conduct"]}', '{"root":{"text":"breach","meaning":"break (打破)"},"logic":"打破規則，即「違反」。"}', 'breach of contract / security breach / data breach', '[{"en":"The lawsuit alleges a breach of contract.","zh-TW":"訴訟指控違反合約。"},{"en":"A data breach exposed customer information.","zh-TW":"資料外洩暴露了客戶資訊。"}]', NULL, NULL, 2, 397, NULL),
(398, 'bread', '/brɛd/', 'noun', '{"zh-TW":["麵包"],"en":["food made from flour and water"]}', NULL, 'slice of bread / bread and butter', '[{"en":"I''d like some bread, please.","zh-TW":"請給我一些麵包。"},{"en":"Teaching is her bread and butter.","zh-TW":"教書是她的生計。"}]', NULL, NULL, 2, 398, NULL),
(399, 'break', '/breɪk/', 'noun', '{"zh-TW":["休息；打破","打破；休息"],"en":["a pause in work","to separate into pieces"]}', NULL, 'take a break / break down; break down / take a break', '[{"en":"Let''s take a 15-minute break.","zh-TW":"我們休息15分鐘吧。"},{"en":"The machine broke down yesterday.","zh-TW":"機器昨天故障了。"},{"en":"Be careful not to break it.","zh-TW":"小心別打破了。"},{"en":"Let''s take a short break.","zh-TW":"讓我們休息一下。"}]', '{"verb":"break","noun":"break","noun2":"breakdown","adjective":"breakable"}', NULL, 2, 399, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(400, 'break-even', '/breɪk ˈiːvən/', 'noun', '{"zh-TW":["損益兩平；盈虧平衡點"],"en":["the point at which revenues equal costs"]}', NULL, 'reach break-even / break-even point', '[{"en":"The company expects to reach break-even by the third quarter.","zh-TW":"公司預計在第三季度達到損益兩平。"},{"en":"Calculating the break-even point helps set realistic sales targets.","zh-TW":"計算盈虧平衡點有助於設定切實可行的銷售目標。"}]', '{"adjective":"break-even"}', NULL, 4, 400, NULL),
(401, 'breakeven', '/ˈbreɪkˌiːvən/', 'noun', '{"zh-TW":["損益平衡點"],"en":["the point at which revenues equal costs with neither profit nor loss"]}', NULL, 'breakeven point / reach breakeven / breakeven analysis', '[{"en":"The startup reached breakeven after 18 months.","zh-TW":"新創公司在18個月後達到了損益平衡點。"},{"en":"Breakeven analysis helps determine minimum sales needed.","zh-TW":"損益平衡分析有助於確定所需的最低銷售量。"}]', '{"verb":"break even"}', NULL, 3, 401, NULL),
(402, 'breakthrough', '/ˈbreɪkθruː/', 'noun', '{"zh-TW":["突破"],"en":["a sudden important development or discovery"]}', '{"root":{"text":"break","meaning":"break (打破)"},"suffix":{"text":"through","meaning":"through (穿過)"},"logic":"打破穿過障礙，即「突破」。"}', 'major breakthrough / technological breakthrough', '[{"en":"The research team achieved a major breakthrough.","zh-TW":"研究團隊取得了重大突破。"},{"en":"This technology represents a breakthrough in AI.","zh-TW":"這項技術代表了人工智慧的突破。"}]', NULL, NULL, 4, 402, NULL),
(403, 'breath', '/brɛθ/', 'noun', '{"zh-TW":["呼吸；氣息"],"en":["the air that goes in and out of lungs"]}', NULL, 'take a breath / out of breath', '[{"en":"Take a deep breath.","zh-TW":"深呼吸。"},{"en":"She was out of breath from running.","zh-TW":"她跑得上氣不接下氣。"}]', '{"verb":"breathe","adjective":"breathless"}', NULL, 2, 403, NULL),
(404, 'breeze', '/briːz/', 'noun', '{"zh-TW":["微風"],"en":["a gentle wind"]}', '{"root":{"text":"breeze","meaning":"light wind (輕風)"},"logic":"指輕柔的風。"}', 'a gentle breeze / sea breeze', '[{"en":"A cool breeze blew in from the ocean.","zh-TW":"一陣涼爽的海風吹來。"},{"en":"The curtains moved gently in the breeze.","zh-TW":"窗簾在微風中輕輕飄動。"}]', '{"adjective":"breezy"}', NULL, 2, 404, NULL),
(405, 'bridge', '/brɪdʒ/', 'noun', '{"zh-TW":["橋；橋梁"],"en":["a structure over a river or road"]}', NULL, 'build a bridge / bridge the gap', '[{"en":"They built a new bridge over the river.","zh-TW":"他們在河上建了一座新橋。"},{"en":"Education bridges the gap.","zh-TW":"教育彌合了差距。"}]', NULL, NULL, 2, 405, NULL),
(406, 'brief', '/briːf/', 'adjective', '{"zh-TW":["【主要意義-形容詞】簡短的；短暫的","【次要意義-動詞】簡報；叮囑；向……作摘要說明","【次要意義-名詞】概要；任務說明；（律師的）案件摘要"],"en":["[primary - adjective] short in duration or length","[secondary - verb] to give someone essential information before a task","[secondary - noun] a set of instructions or a summary of key information"]}', '{"root":{"text":"brev","meaning":"short (短)"},"logic":"短的，即「簡短的」。"}', 'brief someone on / be briefed about / mission brief / design brief', '[{"en":"Managers were briefed on the new safety procedures before implementation.","zh-TW":"管理人員在實施前已就新安全程序進行了匯報。"},{"en":"The design team received a detailed brief outlining the client requirements.","zh-TW":"設計團隊收到了一份詳細說明客戶需求的任務說明書。"},{"en":"The consultant was briefed thoroughly before meeting the board.","zh-TW":"顧問在與董事會見面之前已進行了全面的情況說明。"}]', '{"noun":"briefing","adverb":"briefly"}', '動詞 brief = 「向某人匯報/說明情況」，名詞 brief = 「任務說明/概要」，TOEIC 商業會議或專案管理文章的常見用法，考生容易只記住形容詞「簡短的」。', 2, 406, 830),
(407, 'briefing', '/ˈbriːfɪŋ/', 'noun', '{"zh-TW":["簡報；情況說明"],"en":["a meeting where information is given to prepare people"]}', NULL, 'daily briefing / press briefing', '[{"en":"The manager gave a briefing on the quarterly results.","zh-TW":"經理就季度業績進行了簡報。"},{"en":"All staff attended a safety briefing before the site visit.","zh-TW":"所有員工在現場參觀前參加了安全簡報。"}]', '{"verb":"brief","adjective":"briefed"}', NULL, 3, 407, NULL),
(408, 'bright', '/braɪt/', 'adjective', '{"zh-TW":["明亮的；聰明的"],"en":["giving out much light; intelligent"]}', NULL, 'bright future / bright idea', '[{"en":"The sun is very bright today.","zh-TW":"今天太陽很亮。"},{"en":"She has a bright future ahead.","zh-TW":"她前途光明。"}]', '{"noun":"brightness","adverb":"brightly","verb":"brighten"}', NULL, 2, 408, NULL),
(409, 'brilliant', '/ˈbrɪliənt/', 'adjective', '{"zh-TW":["傑出的；明亮的"],"en":["exceptionally clever or talented","very bright"]}', '{"root":{"text":"brill","meaning":"shine (閃耀)"},"suffix":{"text":"-iant","meaning":"being (…的)"},"logic":"閃耀著光芒的，即「傑出的」。"}', 'brilliant idea / brilliant career / brilliant color', '[{"en":"She had a brilliant idea for the project.","zh-TW":"她對這個專案有個絕妙的點子。"},{"en":"He has had a brilliant career in science.","zh-TW":"他在科學領域有卓越的職業生涯。"}]', '{"noun":"brilliance","adverb":"brilliantly"}', NULL, 3, 409, NULL),
(410, 'bring', '/brɪŋ/', 'verb', '{"zh-TW":["帶來；引起"],"en":["to carry to a place","to cause","to carry something to a place"]}', NULL, 'bring about / bring up; bring up / bring about', '[{"en":"Please bring your laptop to the meeting.","zh-TW":"請帶你的筆電來開會。"},{"en":"The merger brought about many changes.","zh-TW":"合併帶來了許多變化。"},{"en":"Bring your umbrella.","zh-TW":"把傘帶上。"},{"en":"What brought about this change?","zh-TW":"是什麼引起了這個改變？"}]', '{"verb":"bring"}', NULL, 2, 410, NULL),
(411, 'broad', '/brɔːd/', 'adjective', '{"zh-TW":["廣泛的；寬闊的","寬闊的；廣泛的"],"en":["having a large distance from side to side","covering a wide range","wide; covering a large area"]}', '{"root":{"text":"broad","meaning":"wide (寬)"},"logic":"寬的，即「廣泛的」。"}', 'broad range / broad experience / broad spectrum; broad range / broad daylight', '[{"en":"The company offers a broad range of services.","zh-TW":"公司提供廣泛的服務。"},{"en":"She has broad experience in international trade.","zh-TW":"她在國際貿易方面有廣泛經驗。"},{"en":"The river is very broad here.","zh-TW":"河在這裡非常寬。"},{"en":"It happened in broad daylight.","zh-TW":"這發生在光天化日之下。"}]', '{"adverb":"broadly","verb":"broaden"}', NULL, 2, 411, NULL),
(412, 'broadcast', '/ˈbrɔːdkæst/', 'verb', '{"zh-TW":["廣播；播放"],"en":["to send out programs by radio or TV"]}', NULL, 'live broadcast / broadcast news', '[{"en":"The game will be broadcast live.","zh-TW":"比賽將現場直播。"},{"en":"The news is broadcast at six.","zh-TW":"新聞在六點播出。"}]', '{"noun":"broadcast","noun2":"broadcaster"}', NULL, 3, 412, 517),
(413, 'broaden', '/ˈbrɔːdən/', 'verb', '{"zh-TW":["擴大；拓寬"],"en":["to make something wider or more inclusive in scope"]}', NULL, 'broaden the scope / broaden the customer base', '[{"en":"The company broadened its product range to include health supplements.","zh-TW":"公司擴大了其產品系列以包括健康補充劑。"},{"en":"The partnership broadened the firm''s access to new markets.","zh-TW":"夥伴關係擴大了公司進入新市場的管道。"}]', '{"adjective":"broadened","noun":"broadening"}', NULL, 3, 413, NULL),
(414, 'broken', '/ˈbroʊkən/', 'adjective', '{"zh-TW":["破碎的；壞掉的"],"en":["damaged and no longer working"]}', NULL, 'broken heart / broken promise', '[{"en":"The window is broken.","zh-TW":"窗戶破了。"},{"en":"He has a broken heart.","zh-TW":"他傷心透了。"}]', NULL, NULL, 2, 414, NULL),
(415, 'broker', '/ˈbroʊkər/', 'noun', '{"zh-TW":["經紀人；仲介"],"en":["an agent who arranges transactions between buyers and sellers"]}', NULL, 'insurance broker / real estate broker / commodity broker', '[{"en":"The real estate broker negotiated a favorable lease on our behalf.","zh-TW":"房地產經紀人代我們協商了有利的租賃條件。"},{"en":"A broker was hired to arrange the bond issuance.","zh-TW":"聘請了一名經紀人安排債券發行。"}]', '{"verb":"broker","noun":"brokerage"}', NULL, 2, 415, 831),
(416, 'brokerage', '/ˈbroʊkərɪdʒ/', 'noun', '{"zh-TW":["經紀公司；佣金"],"en":["a firm that buys and sells securities on behalf of clients; also the fee charged"]}', NULL, 'brokerage firm / open a brokerage account / brokerage fee / online brokerage', '[{"en":"She moved her investments to an online brokerage to reduce fees.","zh-TW":"她將投資轉移到網路經紀公司以降低費用。"},{"en":"The brokerage charged a $10 commission per trade.","zh-TW":"該經紀公司每筆交易收取10美元佣金。"}]', '{"noun":"broker","verb":"broker"}', NULL, 3, 416, NULL),
(417, 'brook', '/brʊk/', 'verb, noun', '{"zh-TW":["【主要意義-名詞】小溪；小河","【次要意義-動詞】容忍；忍受（常用於否定句）"],"en":["[primary - noun] a small stream","[secondary - verb] to tolerate or allow, usually in negative constructions"]}', NULL, 'brook no delay / brook no interference / will not brook', '[{"en":"The CEO will brook no interference in his decision-making process.","zh-TW":"執行長不會容忍任何對其決策過程的干涉。"},{"en":"The new regulations brook no exceptions for established companies.","zh-TW":"新法規對老牌企業不容任何例外。"},{"en":"She brooked no nonsense from her subordinates.","zh-TW":"她不容許下屬有任何胡鬧行為。"}]', NULL, '動詞 brook 幾乎只出現在否定句中（brook no + noun），意為「不容忍」，是正式書面英語常見用法，TOEIC 閱讀中出現時常讓考生誤認為名詞小溪。', 2, 417, NULL),
(418, 'broth', '/brɒθ/', 'noun', '{"zh-TW":["高湯；清湯"],"en":["a thin soup made from meat or vegetables"]}', NULL, 'chicken broth / vegetable broth', '[{"en":"A bowl of hot broth is comforting on a cold day.","zh-TW":"寒冷的天氣裡，一碗熱高湯令人感到溫暖。"},{"en":"The chef used a rich beef broth as the base for the soup.","zh-TW":"廚師用濃郁的牛肉高湯作為湯的基底。"}]', NULL, NULL, 2, 418, NULL),
(419, 'brother', '/ˈbrʌðər/', 'noun', '{"zh-TW":["兄弟"],"en":["a male sibling"]}', NULL, 'big brother / brother-in-law', '[{"en":"My brother is older than me.","zh-TW":"我哥哥比我大。"},{"en":"They treat each other like brothers.","zh-TW":"他們像兄弟一樣對待彼此。"}]', '{"noun2":"brotherhood"}', NULL, 3, 419, NULL),
(420, 'brown', '/braʊn/', 'adjective', '{"zh-TW":["棕色的"],"en":["the color of wood or earth"]}', NULL, 'brown sugar / brown bag', '[{"en":"She has brown eyes.","zh-TW":"她有棕色的眼睛。"},{"en":"The leaves turn brown in autumn.","zh-TW":"秋天葉子變成棕色。"}]', NULL, NULL, 2, 420, NULL),
(421, 'browse', '/braʊz/', 'verb', '{"zh-TW":["瀏覽；隨意看看"],"en":["to look at things casually without intent to buy"]}', '{"root":{"text":"browse","meaning":"young shoots (嫩芽)"},"logic":"原指動物啃食嫩芽，後引申為隨意翻閱。"}', 'browse through / browse the internet', '[{"en":"I spent an hour browsing in the bookstore.","zh-TW":"我在書店裡瀏覽了一個小時。"},{"en":"She likes to browse online shops during lunch.","zh-TW":"她喜歡午餐時瀏覽網路商店。"}]', '{"noun":"browser"}', NULL, 2, 421, NULL),
(422, 'browser', '/ˈbraʊzər/', 'noun', '{"zh-TW":["瀏覽器"],"en":["a program for accessing websites"]}', NULL, 'web browser / browser history', '[{"en":"Which web browser do you use?","zh-TW":"你使用哪個網頁瀏覽器？"},{"en":"Clear your browser history.","zh-TW":"清除你的瀏覽記錄。"}]', '{"verb":"browse"}', NULL, 3, 422, NULL),
(423, 'brunch', '/brʌntʃ/', 'noun', '{"zh-TW":["早午餐"],"en":["a late morning meal combining breakfast and lunch"]}', NULL, 'weekend brunch / brunch menu', '[{"en":"The hotel serves a popular weekend brunch.","zh-TW":"飯店供應受歡迎的週末早午餐。"},{"en":"We went out for brunch after the morning meeting.","zh-TW":"早上的會議結束後我們出去吃早午餐。"}]', NULL, NULL, 2, 423, NULL),
(424, 'brush', '/brʌʃ/', 'noun', '{"zh-TW":["刷子；刷"],"en":["a tool with bristles for cleaning or painting"]}', NULL, 'tooth brush / brush up on', '[{"en":"Brush your teeth twice a day.","zh-TW":"每天刷牙兩次。"},{"en":"I need to brush up on my French.","zh-TW":"我需要複習一下法語。"}]', '{"verb":"brush"}', NULL, 2, 424, NULL),
(425, 'budget', '/ˈbʌdʒɪt/', 'noun', '{"zh-TW":["預算"],"en":["an estimate of income and expenditure for a set period"]}', '{"root":{"text":"bougette","meaning":"small bag (小袋子)"},"logic":"裝錢的小袋子（分配金額），即「預算」。"}', 'within budget / over budget / annual budget', '[{"en":"The project was completed within budget.","zh-TW":"專案在預算內完成。"},{"en":"We need to cut the budget by 10%.","zh-TW":"我們需要削減10%的預算。"}]', '{"adjective":"budgetary"}', NULL, 2, 425, 13),
(426, 'buffer', '/ˈbʌfər/', 'noun', '{"zh-TW":["緩衝；備用時間"],"en":["a reserve of time or resources included to handle unexpected issues"]}', NULL, 'time buffer / budget buffer / add a buffer / contingency buffer', '[{"en":"A two-week buffer was added to the schedule for unexpected delays.","zh-TW":"排程增加了兩週的緩衝時間以應對意外延遲。"},{"en":"Budget buffers protect projects from cost overruns.","zh-TW":"預算緩衝保護項目免受成本超支。"}]', '{"verb":"buffer","adjective":"buffered"}', NULL, 2, 426, NULL),
(427, 'buffet', '/ˈbʊfeɪ/', 'noun', '{"zh-TW":["自助餐"],"en":["a meal where guests serve themselves from a variety of dishes"]}', NULL, 'breakfast buffet / buffet style', '[{"en":"The Sunday brunch buffet is very popular.","zh-TW":"週日早午餐自助餐非常受歡迎。"},{"en":"The buffet includes over thirty different dishes.","zh-TW":"自助餐包含三十多種不同菜餚。"}]', NULL, NULL, 2, 427, NULL),
(428, 'build', '/bɪld/', 'verb', '{"zh-TW":["建造；建立"],"en":["to construct","to develop over time","to make something by putting parts together"]}', NULL, 'build up / build a team; build up / build on', '[{"en":"We need to build a strong team.","zh-TW":"我們需要建立一支強大的團隊。"},{"en":"They are building a new factory.","zh-TW":"他們正在建造一座新工廠。"},{"en":"They''re building a new house.","zh-TW":"他們正在建一棟新房子。"},{"en":"We need to build trust.","zh-TW":"我們需要建立信任。"}]', '{"verb":"build","noun":"building","noun2":"builder"}', NULL, 2, 428, NULL),
(429, 'bulk', '/bʌlk/', 'noun', '{"zh-TW":["大量；大批","體積"],"en":["a large quantity or mass","a large quantity","the mass or size of something"]}', '{"root":{"text":"bulk","meaning":"heap (堆)"},"logic":"大堆的量，即「大量」。"}', 'in bulk / bulk order / bulk purchase', '[{"en":"Ordering in bulk reduces the unit cost.","zh-TW":"大量訂購可降低單位成本。"},{"en":"The bulk of our revenue comes from overseas.","zh-TW":"我們大部分營收來自海外。"},{"en":"Buying in bulk saves money.","zh-TW":"大量採購可以省錢。"},{"en":"The bulk of the work has been completed.","zh-TW":"大部分的工作已經完成。"}]', '{"adjective":"bulky"}', NULL, 1, 429, 832),
