(431, 'bundling', '/ˈbʌndəlɪŋ/', 'noun', '{"zh-TW":["捆綁銷售；組合定價"],"en":["selling multiple products or services together as a package at a combined price"]}', NULL, 'product bundling / bundling strategy / price bundling', '[{"en":"Bundling software with hardware increased average order value.","zh-TW":"將軟體與硬體捆綁銷售提高了平均訂單價值。"},{"en":"Streaming services use bundling to reduce churn.","zh-TW":"串流服務使用捆綁銷售來降低流失率。"}]', '{"verb":"bundle"}', NULL, 3, 431, NULL),
(432, 'burden', '/ˈbɜːrdn/', 'noun', '{"zh-TW":["負擔；重擔"],"en":["a heavy load; a duty or responsibility that causes worry","a heavy load; a duty that causes worry"]}', '{"root":{"text":"burden","meaning":"carry (攜帶)"},"logic":"需要攜帶的重量，即「負擔」。"}', 'financial burden / burden on / ease the burden; heavy burden / financial burden / burden of proof', '[{"en":"The new regulations place a heavy burden on small businesses.","zh-TW":"新法規對小企業造成沉重負擔。"},{"en":"Tax cuts helped ease the financial burden on families.","zh-TW":"減稅幫助減輕了家庭的經濟負擔。"},{"en":"The tax increase places a burden on families.","zh-TW":"增稅對家庭造成負擔。"},{"en":"She didn''t want to be a burden to her children.","zh-TW":"她不想成為孩子的負擔。"}]', '{"adjective":"burdensome","verb":"burden"}', NULL, 2, 432, NULL),
(433, 'bureau', '/ˈbjʊərəʊ/', 'noun', '{"zh-TW":["局；署；辦公室"],"en":["a government department or agency","an office for business"]}', '{"root":{"text":"bureau","meaning":"desk/office (桌子/辦公室)"},"logic":"辦公的地方，即「局、署」。"}', 'travel bureau / bureau of statistics', '[{"en":"The Bureau of Labor Statistics released new employment data.","zh-TW":"勞動統計局發布了新的就業數據。"},{"en":"Contact the information bureau for details.","zh-TW":"詳情請聯繫資訊服務處。"}]', '{"noun":"bureaucracy","adjective":"bureaucratic"}', NULL, 2, 433, NULL),
(434, 'bureaucracy', '/bjʊˈrɒkrəsi/', 'noun', '{"zh-TW":["官僚體制；繁文縟節"],"en":["a system of government with many complicated rules"]}', '{"root":{"text":"bureau","meaning":"office (辦公室)"},"suffix":{"text":"-cracy","meaning":"rule (統治)"},"logic":"辦公室統治，即「官僚體制」。"}', 'government bureaucracy / red tape and bureaucracy', '[{"en":"Excessive bureaucracy slows down the approval process.","zh-TW":"過度的官僚體制拖慢了審批流程。"},{"en":"The company reduced internal bureaucracy to improve efficiency.","zh-TW":"公司減少了內部繁文縟節以提高效率。"}]', '{"adjective":"bureaucratic"}', NULL, 4, 434, NULL),
(435, 'burn', '/bɜːrn/', 'verb', '{"zh-TW":["燃燒；燒傷"],"en":["to be on fire; to damage with heat"]}', NULL, 'burn down / burn out', '[{"en":"The candle burned all night.","zh-TW":"蠟燭燃燒了整夜。"},{"en":"She burned her hand on the stove.","zh-TW":"她的手被爐子燙傷了。"}]', NULL, NULL, 1, 435, NULL),
