(438, 'bus', '/bʌs/', 'noun', '{"zh-TW":["公車"],"en":["a large vehicle carrying passengers"]}', NULL, 'bus stop / miss the bus', '[{"en":"I take the bus to work.","zh-TW":"我搭公車上班。"},{"en":"We missed the last bus.","zh-TW":"我們錯過了末班車。"}]', NULL, NULL, 1, 438, NULL),
