(443, 'buy', '/baɪ/', 'verb', '{"zh-TW":["購買","買"],"en":["to obtain something by paying money","to get something by paying money"]}', NULL, 'buy in bulk / buy online; buy into / best buy', '[{"en":"We buy office supplies in bulk.","zh-TW":"我們大量採購辦公用品。"},{"en":"More people buy products online now.","zh-TW":"現在更多人在網路上購物。"},{"en":"I want to buy a new phone.","zh-TW":"我想買一支新手機。"},{"en":"She bought groceries after work.","zh-TW":"她下班後買了雜貨。"}]', '{"verb":"buy","noun":"buyer","noun2":"purchase"}', NULL, 1, 443, NULL),
(444, 'buyback', '/ˈbaɪbæk/', 'noun', '{"zh-TW":["回購"],"en":["a company''s repurchase of its own shares from the market"]}', NULL, 'share buyback / stock buyback / announce a buyback program', '[{"en":"The company announced a 500 million dollar share buyback program.","zh-TW":"公司宣佈了5億美元的股票回購計劃。"},{"en":"Buybacks increase earnings per share by reducing shares outstanding.","zh-TW":"回購通過減少流通股數量提高了每股盈餘。"}]', '{"verb":"buy back"}', NULL, 3, 444, NULL),
