(449, 'cabinet', '/ˈkæbɪnɪt/', 'noun', '{"zh-TW":["內閣；櫥櫃","櫥櫃；內閣"],"en":["the group of senior government ministers","a piece of furniture with shelves","a group of senior government ministers"]}', '{"root":{"text":"cabin","meaning":"small room (小房間)"},"suffix":{"text":"-et","meaning":"small (小)"},"logic":"小房間狀的儲物家具，或指內閣。"}', 'cabinet meeting / cabinet minister; kitchen cabinet / cabinet meeting / filing cabinet', '[{"en":"The cabinet met to discuss the crisis.","zh-TW":"內閣開會討論危機。"},{"en":"She was appointed to the cabinet.","zh-TW":"她被任命進入內閣。"},{"en":"The dishes are in the cabinet above the sink.","zh-TW":"碗盤在水槽上方的櫥櫃裡。"},{"en":"The cabinet approved the new policy.","zh-TW":"內閣批准了新政策。"}]', NULL, NULL, 3, 449, NULL);